                tile[a][b] = counts[a][b].most_common(1)[0][0]
    for a in range(7):
        for b in range(7):
            if tile[a][b] is None:
                options = [(abs(aa-a)+abs(bb-b), tile[aa][bb])
                           for aa in range(7) for bb in range(7)
                           if tile[aa][bb] is not None]
                tile[a][b] = min(options, key=lambda x: x[0])[1]

    for r in range(h):
