            if out[r][c] != 0:
                continue
            # Background/frame regions
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = tile[r % 7][c % 7]
