    out = [row[:] for row in grid]

    # Restore the frame surrounding the patterned area.
    for r in range(h):
        for c in range(w):
            if r < 2:
                out[r][c] = 1
            elif c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4

    # Each patterned row repeats horizontally. Infer its period and the
    # value at each phase from the nonblank cells in that row.
    for r in range(3, h):
        observed = [(c, grid[r][c]) for c in range(3, w)
                    if grid[r][c] != 0]
        best = None
        for p in range(2, 13):
            phases = []
            errors = 0
            for q in range(p):
                vals = [v for c, v in observed if c % p == q]
                if vals:
                    counts = {}
                    for v in vals:
                        counts[v] = counts.get(v, 0) + 1
                    val = max(counts, key=counts.get)
                    errors += len(vals) - counts[val]
                else:
                    val = None
                phases.append(val)
            score = (errors, p)
            if best is None or score < best[0]:
                best = (score, phases)

        phases = best[1]
        for q in range(len(phases)):
            if phases[q] is None:
                # Fill an unseen phase from a nearby phase, consistent with
                # the cyclic color order present in the row.
                known = [(abs(k-q), phases[k]) for k in range(len(phases))
                         if phases[k] is not None]
                phases[q] = min(known, key=lambda x: x[0])[1]

        for c in range(3, w):
            if grid[r][c] == 0:
                out[r][c] = phases[c % len(phases)]
    return out
